	/*
     * @param	event CreateMatterEvent
     */
    @EventHandler( payloadType=CreateMatterEvent.class )
    public void handle( CreateMatterEvent event) {
	    LOGGER.info("handling CreateMatterEvent - " + event );
	    Matter entity = new Matter();
            entity.setMatterId( event.getMatterId() );
            entity.setMatterName( event.getMatterName() );
            entity.setLeadCounsel( event.getLeadCounsel() );
            entity.setMatterType( event.getMatterType() );
            entity.setStatus( event.getStatus() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllMatter( entity );
    }

