    @EventHandler( payloadType=UpdateMatterEvent.class )
    public void handle( UpdateMatterEvent event) {
    	LOGGER.info("handling UpdateMatterEvent - " + event );
    	
	    Matter entity = new Matter();
            entity.setMatterId( event.getMatterId() );
            entity.setMatterName( event.getMatterName() );
            entity.setLeadCounsel( event.getLeadCounsel() );
            entity.setLegalHolds( event.getLegalHolds() );
            entity.setOrganization( event.getOrganization() );
            entity.setDataBreaches( event.getDataBreaches() );
            entity.setContracts( event.getContracts() );
            entity.setMatterType( event.getMatterType() );
            entity.setStatus( event.getStatus() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindMatter( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllMatter( entity );        
    }
    
