    /**
     * Method to retrieve the Matter via an MatterPrimaryKey.
     * @param 	id Long
     * @return 	Matter
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Matter handle( FindMatterQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getMatterId() );
    }
    
    /**
     * Method to retrieve a collection of all Matters
     *
     * @param	query	FindAllMatterQuery 
     * @return 	List<Matter> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Matter> handle( FindAllMatterQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindMatter,
 * but only if the id matches
 *
 * @param		entity	Matter
 */
	protected void emitFindMatter( Matter entity ) {
		LOGGER.info("handling emitFindMatter" );
		
	    queryUpdateEmitter.emit(FindMatterQuery.class,
	                            query -> query.getFilter().getMatterId().equals(entity.getMatterId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllMatter
	 * 
	 * @param		entity	Matter
	 */
	protected void emitFindAllMatter( Matter entity ) {
		LOGGER.info("handling emitFindAllMatter" );
		
	    queryUpdateEmitter.emit(FindAllMatterQuery.class,
	                            query -> true,
	                            entity);
	}

